import { useState } from 'react';
import { useForm } from 'react-hook-form';
import { yupResolver } from '@hookform/resolvers/yup';
import { Box, Button, Checkbox, FormControlLabel, TextField } from '@mui/material';
import schema from '../validations/formAppSchema';

export default function FormApp() {
  const [sent, setSent] = useState(false);

  const {register, handleSubmit, formState: {errors, isSubmitting}, reset} = useForm({
    defaultValues: {
      name: '',
      email: '',
      title: '',
      message: '',
      agreement: false,
    },
    resolver: yupResolver(schema),
  });

  const onSubmit = async (data) => {
    // ここでAPI送信などを実装（いまは疑似送信）
    await new Promise((r) => setTimeout(r, 600));
    setSent(true);
    reset({ name: '', email: '', title: '', message: '', agreement: false });
  };

  return (
    <Box component="form" onSubmit={handleSubmit(onSubmit)} noValidate sx={{maxWidth: 500,}}>{/* formタグを使用しない */}
      {sent && <Box sx={{mb: 1, color: 'success.main'}}>送信が完了しました。</Box>}

      <TextField
        label="お名前"
        placeholder="山田 太郎"
        fullWidth
        margin="normal"
        error={!!errors.name}
        helperText={errors.name?.message}
        {...register('name')}
      />

      <TextField
        label="メールアドレス"
        placeholder="taro@example.com"
        type="email"
        fullWidth
        margin="normal"
        error={!!errors.email}
        helperText={errors.email?.message}
        {...register('email')}
      />

      <TextField
        label="件名"
        placeholder="お問い合わせの件名"
        fullWidth
        margin="normal"
        error={!!errors.title}
        helperText={errors.title?.message}
        {...register('title')}
      />

      <TextField
        label="本文"
        placeholder="お問い合わせ内容をご記入ください"
        fullWidth
        margin="normal"
        multiline
        rows={5}
        error={!!errors.message}
        helperText={errors.message?.message}
        {...register('message')}
      />

      <FormControlLabel
        control={<Checkbox {...register('agreement')} />}
        label="プライバシーポリシーに同意する"
      />
      {errors.agreement && (
        <Box sx={{ color: 'error.main', fontSize: 12 }}>{errors.agreement.message}</Box>
      )}

      <Button type="submit" variant="contained" sx={{ mt: 2 }} disabled={isSubmitting}>
        {isSubmitting ? '送信中…' : '送信'}
      </Button>
    </Box>
  );
}
